/** Apple 风格设计规范与 Shadow DOM 全隔离样式。 */
export declare const STYLES = "\n:host {\n  --fb-z-index-default: 2147483000;\n  --fb-accent: #0071e3;\n  --fb-accent-hover: #0077ed;\n  --fb-accent-active: #006edb;\n  --fb-accent-disabled: #a0c7f5;\n  --fb-focus-ring: rgba(0, 113, 227, 0.28);\n\n  /* \u9ED8\u8BA4\u6D45\u8272\u53D8\u91CF */\n  --fb-bg: #ffffff;\n  --fb-bg-subtle: #f5f5f7;\n  --fb-bg-subtle-hover: #e8e8ed;\n  --fb-text: #1d1d1f;\n  --fb-text-secondary: #86868b;\n  --fb-text-tertiary: #a1a1a6;\n  --fb-border: rgba(0, 0, 0, 0.08);\n  --fb-border-strong: rgba(0, 0, 0, 0.16);\n  --fb-shadow: 0 12px 32px rgba(0, 0, 0, 0.12), 0 2px 6px rgba(0, 0, 0, 0.04);\n  --fb-tab-shadow: 0 4px 14px rgba(0, 0, 0, 0.08), 0 1px 3px rgba(0, 0, 0, 0.05);\n\n  --fb-status-error-bg: #fff2f4;\n  --fb-status-error-border: #ffccd5;\n  --fb-status-error-text: #d70015;\n\n  --fb-status-success-bg: #f0fdf4;\n  --fb-status-success-border: #bbf7d0;\n  --fb-status-success-text: #15803d;\n\n  --fb-status-warn-bg: #fff9eb;\n  --fb-status-warn-border: #fde68a;\n  --fb-status-warn-text: #b45309;\n\n  font-family: -apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"SF Pro Display\",\n    \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", sans-serif;\n  font-size: 14px;\n  line-height: 1.5;\n  color: var(--fb-text);\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n/*\n * [hidden] \u5168\u5C40\u515C\u5E95\uFF08\u5FC5\u987B\u4FDD\u7559\uFF09\u3002\n *\n * \u6D4F\u89C8\u5668\u9ED8\u8BA4\u6837\u5F0F\u8868\u91CC\u7684 [hidden] { display: none } \u662F **UA \u89C4\u5219**\uFF0C\u4F1A\u88AB\u672C\u6587\u4EF6\u7684\n * \u4EFB\u4F55\u4F5C\u8005\u89C4\u5219\u538B\u6389 \u2014\u2014 \u4F8B\u5982 .fb-screenshot-wrap { display: flex } \u4F1A\u8BA9\n * element.hidden = true \u5B8C\u5168\u5931\u6548\uFF1A\u5143\u7D20\u7167\u65E7\u5360\u636E\u7248\u9762\u3002\n *\n * \u5DF2\u53D1\u751F\u8FC7\u7684\u771F\u5B9E\u6545\u969C\uFF08\u5BBF\u4E3B\u672A\u58F0\u660E capture-mode\uFF0C\u5373\u9ED8\u8BA4 off \u7684\u7EDD\u5927\u591A\u6570\u5BBF\u4E3B\uFF09\uFF1A\n * \u9762\u677F\u663E\u793A\u4E00\u4E2A\u7A7A\u7684\u300C\u5F53\u524D\u622A\u56FE / \u70B9\u51FB\u653E\u5927\u300D\u533A\uFF0C\u7F29\u7565\u56FE src \u4E3A\u7A7A \u2192 \u7834\u56FE\u5360\u4F4D\uFF0C\n * \u70B9\u51FB\u4E5F\u65E0\u6CD5\u653E\u5927\uFF08\u65E0\u622A\u56FE\u65F6 openZoomModal \u76F4\u63A5\u8FD4\u56DE\uFF09\u3002\u300C\u79FB\u9664\u622A\u56FE\u300D\u770B\u8D77\u6765\u4E5F\u6BEB\u65E0\u53CD\u5E94\u3002\n *\n * \u56E0\u6B64\u8FD9\u91CC\u7EDF\u4E00\u6062\u590D hidden \u8BED\u4E49\uFF0C\u907F\u514D\u6BCF\u52A0\u4E00\u4E2A\u8BBE\u7F6E display \u7684\u7EC4\u4EF6\u89C4\u5219\u5C31\u91CD\u65B0\u8E29\u4E00\u6B21\u3002\n * \u4F9D\u8D56\u5B83\u7684\u5143\u7D20\u4E0D\u6B62\u622A\u56FE\u5C42\uFF1A\u9762\u677F\u3001\u622A\u56FE\u9884\u89C8\u533A\u4E0E\n * \u300C\u622A\u53D6\u5F53\u524D\u9875\u9762 / \u91CD\u65B0\u622A\u56FE / \u79FB\u9664\u622A\u56FE\u300D\u4E09\u4EF6\u5957\uFF08\u6309\u72B6\u6001\u4E92\u65A5\u663E\u793A\uFF09\u540C\u6837\u9760\u5B83\u515C\u5E95\u3002\n * \u56DE\u5F52\u8986\u76D6\uFF1Ae2e/run_browser.py \u7684 P5a / P5b / P6\uFF08\u53EA\u6709\u771F\u5B9E\u6D4F\u89C8\u5668\u6709\u6837\u5F0F\u7EA7\u8054\uFF09\u3002\n */\n[hidden] {\n  display: none !important;\n}\n\n/* \u663E\u5F0F\u6DF1\u8272\u6216\u7CFB\u7EDF\u6DF1\u8272\u6A21\u5F0F */\n:host([theme=\"dark\"]) {\n  --fb-accent-disabled: #1d4677;\n  --fb-bg: #1c1c1e;\n  --fb-bg-subtle: #2c2c2e;\n  --fb-bg-subtle-hover: #3a3a3c;\n  --fb-text: #f5f5f7;\n  --fb-text-secondary: #98989d;\n  --fb-text-tertiary: #636366;\n  --fb-border: rgba(255, 255, 255, 0.12);\n  --fb-border-strong: rgba(255, 255, 255, 0.24);\n  --fb-shadow: 0 16px 40px rgba(0, 0, 0, 0.45), 0 2px 6px rgba(0, 0, 0, 0.3);\n  --fb-tab-shadow: 0 4px 14px rgba(0, 0, 0, 0.4);\n\n  --fb-status-error-bg: rgba(255, 69, 58, 0.15);\n  --fb-status-error-border: rgba(255, 69, 58, 0.3);\n  --fb-status-error-text: #ff453a;\n\n  --fb-status-success-bg: rgba(48, 209, 88, 0.15);\n  --fb-status-success-border: rgba(48, 209, 88, 0.3);\n  --fb-status-success-text: #30d158;\n\n  --fb-status-warn-bg: rgba(255, 159, 10, 0.15);\n  --fb-status-warn-border: rgba(255, 159, 10, 0.3);\n  --fb-status-warn-text: #ff9f0a;\n}\n\n@media (prefers-color-scheme: dark) {\n  :host(:not([theme=\"light\"]):not([theme=\"dark\"])) {\n    --fb-accent-disabled: #1d4677;\n    --fb-bg: #1c1c1e;\n    --fb-bg-subtle: #2c2c2e;\n    --fb-bg-subtle-hover: #3a3a3c;\n    --fb-text: #f5f5f7;\n    --fb-text-secondary: #98989d;\n    --fb-text-tertiary: #636366;\n    --fb-border: rgba(255, 255, 255, 0.12);\n    --fb-border-strong: rgba(255, 255, 255, 0.24);\n    --fb-shadow: 0 16px 40px rgba(0, 0, 0, 0.45), 0 2px 6px rgba(0, 0, 0, 0.3);\n    --fb-tab-shadow: 0 4px 14px rgba(0, 0, 0, 0.4);\n\n    --fb-status-error-bg: rgba(255, 69, 58, 0.15);\n    --fb-status-error-border: rgba(255, 69, 58, 0.3);\n    --fb-status-error-text: #ff453a;\n\n    --fb-status-success-bg: rgba(48, 209, 88, 0.15);\n    --fb-status-success-border: rgba(48, 209, 88, 0.3);\n    --fb-status-success-text: #30d158;\n\n    --fb-status-warn-bg: rgba(255, 159, 10, 0.15);\n    --fb-status-warn-border: rgba(255, 159, 10, 0.3);\n    --fb-status-warn-text: #ff9f0a;\n  }\n}\n\n/* \u9690\u85CF\u5BBF\u4E3B\u63A7\u5236 */\n:host([show-launcher=\"false\"]) .fb-launcher {\n  display: none !important;\n}\n\n/* ---- \u4FA7\u8FB9\u8D34\u8FB9\u5165\u53E3\u6807\u7B7E ---- */\n.fb-launcher {\n  position: fixed;\n  z-index: var(--fb-z-index, var(--fb-z-index-default));\n  bottom: clamp(16px, var(--fb-launcher-bottom, 25%), calc(100vh - 64px));\n  right: 0;\n  left: auto;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  min-height: 44px;\n  min-width: 44px;\n  padding: 8px 12px 8px 10px;\n  border: 1px solid var(--fb-border);\n  border-right: none;\n  border-radius: 12px 0 0 12px;\n  background: var(--fb-bg);\n  color: var(--fb-text);\n  font-size: 13px;\n  font-weight: 500;\n  cursor: pointer;\n  box-shadow: var(--fb-tab-shadow);\n  transition: transform 0.18s cubic-bezier(0.16, 1, 0.3, 1),\n              background 0.18s ease,\n              opacity 0.18s ease;\n  user-select: none;\n  -webkit-user-select: none;\n}\n\n.fb-launcher:hover {\n  transform: translateX(-3px);\n  background: var(--fb-bg-subtle);\n}\n\n.fb-launcher:active {\n  transform: translateX(-1px);\n}\n\n.fb-launcher:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 1px;\n}\n\n.fb-launcher-icon {\n  width: 16px;\n  height: 16px;\n  flex-shrink: 0;\n  fill: currentColor;\n  color: var(--fb-accent);\n}\n\n:host([side=\"left\"]) .fb-launcher {\n  right: auto;\n  left: 0;\n  padding: 8px 10px 8px 12px;\n  border-left: none;\n  border-right: 1px solid var(--fb-border);\n  border-radius: 0 12px 12px 0;\n}\n\n:host([side=\"left\"]) .fb-launcher:hover {\n  transform: translateX(3px);\n}\n\n:host([side=\"left\"]) .fb-launcher:active {\n  transform: translateX(1px);\n}\n\n/* ---- \u7075\u611F\u7403 (Inspiration Orb) ----\n   T1 \u89C6\u89C9\uFF1A\u9759\u6B62 48px\u3001\u62D6\u52A8\u4E2D\u5C55\u5F00\u5230 72px\uFF1B\u900F\u660E\u4E2D\u5FC3\u3001\u767D\u8272\u9AD8\u5149\u8FB9\u7F18\u3001\n   \u9752\uFF0F\u7D2B\uFF0F\u6696\u6A59\u4F4E\u900F\u660E\u5EA6\u5149\u6655\u3002**\u6E10\u53D8\u5149\u6548\u53EA\u5141\u8BB8\u51FA\u73B0\u5728\u7075\u611F\u7403\u4E0A**\u3002 */\n.fb-orb {\n  position: fixed;\n  z-index: var(--fb-z-index, var(--fb-z-index-default));\n  bottom: clamp(16px, var(--fb-launcher-bottom, 25%), calc(100vh - 64px));\n  right: 20px;\n  left: auto;\n  width: 48px;\n  height: 48px;\n  min-width: 48px;\n  min-height: 48px;\n  border-radius: 50%;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  border: 1px solid rgba(125, 125, 130, 0.35);\n  background: transparent;\n  color: var(--fb-text);\n  cursor: grab;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12), 0 1px 3px rgba(0, 0, 0, 0.06);\n  touch-action: none;\n  user-select: none;\n  -webkit-user-select: none;\n  transition: transform 0.18s cubic-bezier(0.16, 1, 0.3, 1),\n              box-shadow 0.18s ease;\n}\n\n:host([side=\"left\"]) .fb-orb {\n  right: auto;\n  left: 20px;\n}\n\n.fb-orb:hover:not(.is-dragging) {\n  transform: scale(1.06);\n}\n\n.fb-orb:active:not(.is-dragging) {\n  transform: scale(1.1);\n}\n\n/* \u62D6\u52A8\u4E2D\uFF1A\u5C3A\u5BF8\u5C55\u5F00\u7531\u5185\u8054 transform scale(1.5)\uFF0848\u219272px\uFF09\u5B8C\u6210\uFF0C\u6B64\u5904\u5173\u95ED\u8FC7\u6E21 */\n.fb-orb.is-dragging {\n  cursor: grabbing;\n  transition: none !important;\n  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.22), 0 2px 6px rgba(0, 0, 0, 0.1);\n}\n\n.fb-orb:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 2px;\n}\n\n/* \u900F\u660E\u4E2D\u5FC3 + \u767D\u8272\u9AD8\u5149\u8FB9\u7F18\uFF08\u5185\u5C42\uFF09 */\n.fb-orb-core,\n.fb-orb-glow {\n  position: absolute;\n  border-radius: 50%;\n  pointer-events: none;\n}\n\n.fb-orb-core {\n  inset: 0;\n  background: radial-gradient(\n    circle at 50% 50%,\n    rgba(255, 255, 255, 0) 0%,\n    rgba(255, 255, 255, 0) 44%,\n    rgba(255, 255, 255, 0.9) 60%,\n    rgba(255, 255, 255, 0.35) 74%,\n    rgba(255, 255, 255, 0) 84%\n  );\n  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.55);\n}\n\n/* \u9752\uFF0F\u7D2B\uFF0F\u6696\u6A59\u4F4E\u900F\u660E\u5EA6\u5149\u6655\uFF08\u5916\u5C42\uFF0C\u7F13\u6162\u6D41\u52A8\uFF09 */\n.fb-orb-glow {\n  inset: -5px;\n  background: conic-gradient(\n    from 0deg,\n    rgba(0, 200, 255, 0.38),\n    rgba(160, 92, 255, 0.34),\n    rgba(255, 158, 64, 0.32),\n    rgba(0, 200, 255, 0.38)\n  );\n  filter: blur(7px);\n  opacity: 0.7;\n  animation: fb-orb-flow 7s linear infinite;\n}\n\n@keyframes fb-orb-flow {\n  from { transform: rotate(0deg); }\n  to { transform: rotate(360deg); }\n}\n\n:host([theme=\"dark\"]) .fb-orb {\n  border: 1px solid rgba(255, 255, 255, 0.22);\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.45);\n}\n\n@media (prefers-color-scheme: dark) {\n  :host(:not([theme=\"light\"]):not([theme=\"dark\"])) .fb-orb {\n    border: 1px solid rgba(255, 255, 255, 0.22);\n    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.45);\n  }\n}\n\n/* \u63A7\u5236 launcher \u6A21\u5F0F\u663E\u793A/\u9690\u85CF */\n:host(:not([launcher-mode=\"orb\"])) .fb-orb {\n  display: none !important;\n}\n\n:host([launcher-mode=\"orb\"]) .fb-tab-launcher {\n  display: none !important;\n}\n\n/* \u9762\u677F\u6253\u5F00\u65F6\u9690\u85CF\u6807\u7B7E */\n.fb-launcher.is-hidden {\n  display: none !important;\n}\n\n/* ---- \u684C\u9762\u5706\u89D2\u6D6E\u5C42\u9762\u677F\uFF08\u65E0\u906E\u7F69\u3001\u4E0D\u6324\u538B\u5E03\u5C40\u3001\u4E0D\u9501\u6EDA\u52A8\uFF09 ----\n   \u51BB\u7ED3\u89C4\u683C\uFF1A\u684C\u9762\u5BBD 440px\uFF0C\u6700\u5927\u9AD8 min(720px, \u89C6\u53E3\u9AD8\u221232px)\uFF1B768px \u4EE5\u4E0B\u5168\u5C4F\u3002 */\n.fb-panel {\n  position: fixed;\n  bottom: 16px;\n  right: 16px;\n  left: auto;\n  top: auto;\n  z-index: var(--fb-z-index, var(--fb-z-index-default));\n  width: min(440px, calc(100vw - 32px));\n  max-height: min(720px, calc(100dvh - 32px));\n  height: auto;\n  box-sizing: border-box;\n  background: var(--fb-bg);\n  border: 1px solid var(--fb-border);\n  border-radius: 16px;\n  box-shadow: var(--fb-shadow);\n  display: flex;\n  flex-direction: column;\n  opacity: 0;\n  transform: scale(0.96) translateY(8px);\n  pointer-events: none;\n  visibility: hidden;\n  transition: opacity 0.2s cubic-bezier(0.16, 1, 0.3, 1),\n              transform 0.2s cubic-bezier(0.16, 1, 0.3, 1),\n              visibility 0.2s;\n  overflow: hidden;\n}\n\n.fb-panel.is-open {\n  opacity: 1;\n  transform: scale(1) translateY(0);\n  pointer-events: auto;\n  visibility: visible;\n}\n\n:host([side=\"left\"]) .fb-panel {\n  right: auto;\n  left: 16px;\n}\n\n/* ---- \u79FB\u52A8\u7AEF\u5168\u5C4F\u5E03\u5C40\uFF08\u65AD\u70B9 768px\uFF09 ---- */\n@media (max-width: 767.98px) {\n  .fb-panel {\n    bottom: 0;\n    top: 0;\n    left: 0;\n    right: 0;\n    width: 100vw;\n    max-height: 100dvh;\n    height: 100dvh;\n    border-radius: 0;\n    border: none;\n    box-shadow: none;\n    transform: translateY(100%);\n    padding-top: env(safe-area-inset-top, 0);\n    padding-bottom: env(safe-area-inset-bottom, 0);\n  }\n\n  .fb-panel.is-open {\n    transform: translateY(0);\n  }\n}\n\n/* ---- \u9762\u677F\u5934\u90E8 ---- */\n.fb-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 18px;\n  border-bottom: 1px solid var(--fb-border);\n  flex-shrink: 0;\n}\n\n.fb-title-group {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.fb-header-icon {\n  width: 18px;\n  height: 18px;\n  fill: currentColor;\n  color: var(--fb-accent);\n  flex-shrink: 0;\n}\n\n.fb-header h2 {\n  margin: 0;\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--fb-text);\n  letter-spacing: -0.01em;\n}\n\n.fb-header-meta {\n  font-size: 11px;\n  color: var(--fb-text-tertiary);\n  margin-left: 4px;\n}\n\n.fb-close {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 32px;\n  height: 32px;\n  border: none;\n  background: var(--fb-bg-subtle);\n  color: var(--fb-text-secondary);\n  border-radius: 50%;\n  cursor: pointer;\n  padding: 0;\n  transition: background 0.15s, color 0.15s;\n}\n\n.fb-close:hover {\n  background: var(--fb-bg-subtle-hover);\n  color: var(--fb-text);\n}\n\n/* \u547D\u4E2D\u533A\u6269\u5230 \u226544px\uFF08\u4E0D\u6539\u53D8\u89C6\u89C9\u5C3A\u5BF8\uFF0C\u76F8\u90BB\u6309\u94AE\u95F4\u8DDD\u6309 16px \u6392\u5E03\u907F\u514D\u91CD\u53E0\uFF09 */\n.fb-close::after,\n.fb-icon-btn::after {\n  content: \"\";\n  position: absolute;\n  inset: -6px;\n}\n\n.fb-close:focus-visible,\n.fb-submit:focus-visible,\n.fb-btn-secondary:focus-visible,\n.fb-task-link:focus-visible,\n.fb-retry-btn:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 2px;\n}\n\n/* ---- \u9762\u677F\u4E3B\u4F53 ----\n   \u987A\u5E8F\uFF08T2.6\uFF09\uFF1A\u53CD\u9988\u63CF\u8FF0 \u2192 \u56FE\u7247\u8BC1\u636E \u2192 \u53EF\u6298\u53E0\u65E5\u5FD7 \u2192 \u72B6\u6001 \u2192 \u56FA\u5B9A\u63D0\u4EA4\u533A\u3002 */\n.fb-body {\n  flex: 1;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: 16px 18px 0;\n  gap: 12px;\n}\n\n.fb-prompt {\n  font-size: 13px;\n  font-weight: 500;\n  color: var(--fb-text-secondary);\n  margin: 0;\n}\n\n.fb-textarea-wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  flex: 1;\n  min-height: 150px;\n}\n\n.fb-textarea {\n  width: 100%;\n  box-sizing: border-box;\n  flex: 1;\n  min-height: 150px;\n  resize: none;\n  padding: 12px 14px;\n  border: 1px solid var(--fb-border);\n  border-radius: 10px;\n  background: var(--fb-bg-subtle);\n  font: inherit;\n  font-size: 14px;\n  color: var(--fb-text);\n  line-height: 1.5;\n  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;\n}\n\n.fb-textarea:focus {\n  outline: none;\n  background: var(--fb-bg);\n  border-color: var(--fb-accent);\n  box-shadow: 0 0 0 3px var(--fb-focus-ring);\n}\n\n.fb-textarea:disabled {\n  opacity: 0.65;\n  cursor: not-allowed;\n}\n\n.fb-counter-row {\n  display: flex;\n  justify-content: flex-end;\n}\n\n.fb-counter {\n  color: var(--fb-text-tertiary);\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n}\n\n.fb-counter.is-over {\n  color: var(--fb-status-error-text);\n  font-weight: 600;\n}\n\n/* ---- \u72B6\u6001\u533A\u4E0E\u5361\u7247 ---- */\n.fb-status-region {\n  min-height: 1.4em;\n  font-size: 13px;\n  color: var(--fb-text-secondary);\n}\n\n.fb-status-card {\n  border-radius: 10px;\n  padding: 12px 14px;\n  border: 1px solid;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  font-size: 13px;\n}\n\n.fb-status-card p {\n  margin: 0;\n  line-height: 1.45;\n}\n\n.fb-status-card.is-error {\n  background: var(--fb-status-error-bg);\n  border-color: var(--fb-status-error-border);\n  color: var(--fb-status-error-text);\n}\n\n.fb-status-card.is-success {\n  background: var(--fb-status-success-bg);\n  border-color: var(--fb-status-success-border);\n  color: var(--fb-status-success-text);\n}\n\n.fb-status-card.is-warn {\n  background: var(--fb-status-warn-bg);\n  border-color: var(--fb-status-warn-border);\n  color: var(--fb-status-warn-text);\n}\n\n.fb-card-actions {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 4px;\n}\n\n.fb-task-link {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  color: var(--fb-accent);\n  font-weight: 500;\n  text-decoration: none;\n}\n\n.fb-task-link:hover {\n  text-decoration: underline;\n}\n\n.fb-btn-secondary {\n  border: 1px solid var(--fb-border-strong);\n  background: var(--fb-bg);\n  color: var(--fb-text);\n  border-radius: 8px;\n  min-height: 44px;\n  padding: 8px 14px;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: background 0.15s;\n}\n\n.fb-btn-secondary:hover {\n  background: var(--fb-bg-subtle-hover);\n}\n\n/* ---- \u5E95\u90E8\u64CD\u4F5C\u533A\uFF08\u56FA\u5B9A\u63D0\u4EA4\u533A\uFF09\uFF1A\u6EDA\u52A8\u65F6\u59CB\u7EC8\u8D34\u5728\u9762\u677F\u5E95\u90E8 ---- */\n.fb-footer {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-top: auto;\n  position: sticky;\n  bottom: 0;\n  z-index: 1;\n  background: var(--fb-bg);\n  border-top: 1px solid var(--fb-border);\n  padding: 10px 0 16px;\n}\n\n.fb-submit {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 44px;\n  padding: 0 18px;\n  border: none;\n  border-radius: 980px;\n  background: var(--fb-accent);\n  color: #fff;\n  font: inherit;\n  font-size: 14px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: background 0.15s ease, transform 0.1s ease;\n}\n\n.fb-submit:hover:not(:disabled) {\n  background: var(--fb-accent-hover);\n}\n\n.fb-submit:active:not(:disabled) {\n  background: var(--fb-accent-active);\n  transform: scale(0.99);\n}\n\n.fb-submit:disabled {\n  background: var(--fb-accent-disabled);\n  cursor: not-allowed;\n}\n\n.fb-footnote {\n  margin: 0;\n  font-size: 11px;\n  color: var(--fb-text-tertiary);\n  text-align: center;\n  line-height: 1.4;\n}\n\n/* ---- \u989D\u5EA6\u4E0E\u9762\u677F\u5185\u767B\u5F55 ----\n   \u6280\u672F / \u8D26\u6237\u4FE1\u606F\u5F31\u5316\u5C55\u793A\uFF08T2.6\uFF09\uFF1A\u66F4\u5C0F\u5B57\u53F7\u3001\u4E09\u7EA7\u6587\u5B57\u8272\uFF0C\u4E0D\u4E0E\u4E3B\u5185\u5BB9\u4E89\u7126\u70B9\u3002 */\n.fb-quota {\n  font-size: 11px;\n  color: var(--fb-text-tertiary);\n  text-align: center;\n  font-variant-numeric: tabular-nums;\n}\n\n.fb-quota-blocked {\n  margin: 0;\n  font-size: 12px;\n  color: var(--fb-status-warn-text);\n  text-align: center;\n  line-height: 1.4;\n}\n\n.fb-login-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 10px 12px;\n  border: 1px solid var(--fb-border);\n  border-radius: 10px;\n  background: var(--fb-bg-subtle);\n}\n\n.fb-login-row {\n  display: flex;\n  gap: 8px;\n}\n\n.fb-login-input {\n  flex: 1;\n  min-width: 0;\n  box-sizing: border-box;\n  padding: 8px 10px;\n  border: 1px solid var(--fb-border-strong);\n  border-radius: 8px;\n  background: var(--fb-bg);\n  color: var(--fb-text);\n  font: inherit;\n  font-size: 13px;\n}\n\n.fb-login-input:focus {\n  outline: none;\n  border-color: var(--fb-accent);\n  box-shadow: 0 0 0 3px var(--fb-focus-ring);\n}\n\n.fb-login-input:disabled {\n  opacity: 0.65;\n  cursor: not-allowed;\n}\n\n.fb-login-error {\n  margin: 0;\n  font-size: 12px;\n  color: var(--fb-status-error-text);\n  line-height: 1.4;\n}\n\n.fb-login-actions {\n  display: flex;\n  gap: 8px;\n  justify-content: flex-end;\n}\n\n/* ---- \u622A\u56FE\u533A\uFF1A\u9884\u89C8\u4E0E\u64CD\u4F5C\u5206\u79BB ----\n   \u9884\u89C8\uFF08.fb-screenshot-wrap\uFF09\u53EA\u5728\u771F\u7684\u6709\u53EF\u6E32\u67D3\u7684\u622A\u56FE URL \u65F6\u53EF\u89C1\uFF1B\n   \u64CD\u4F5C\u533A\uFF08.fb-screenshot-actions\uFF09\u59CB\u7EC8\u5728\u9762\u677F\u91CC\uFF1A\u6CA1\u6709\u622A\u56FE\u65F6\u5B83\u662F\u300C\u622A\u53D6\u5F53\u524D\u9875\u9762\u300D\u3002\n   \u8FD9\u6761\u5206\u5DE5\u662F\u523B\u610F\u7684\u2014\u2014**\u65E0\u622A\u56FE\u65F6\u6574\u4E2A\u622A\u56FE\u533A\u4E00\u8D77\u9690\u85CF**\u4F1A\u8BA9\u9ED8\u8BA4 capture-mode=off\n   \uFF08\u4E0D\u81EA\u52A8\u622A\u56FE\uFF09\u7684\u5BBF\u4E3B\u6CA1\u6709\u4EFB\u4F55\u9996\u6B21\u622A\u56FE / \u8865\u62CD\u5165\u53E3\uFF0C\u800C hidden \u7684\u6309\u94AE\u4E09\u4EF6\u5957\n   \uFF08\u622A\u53D6\u5F53\u524D\u9875\u9762 / \u91CD\u65B0\u622A\u56FE / \u79FB\u9664\u622A\u56FE\uFF09\u53C8\u5FC5\u987B\u771F\u7684\u4E0D\u5360\u7248\u9762\u3002 */\n.fb-shot-area {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n/* ---- \u622A\u56FE\u7F29\u7565\u56FE\u4E0E\u64CD\u4F5C\uFF08v12\uFF1A\u4E24\u5217 120px \u7F29\u7565\u56FE\u7F51\u683C\uFF1BT2.5\uFF09 ----\n   \u56FE\u7247\u5B8C\u6574\u663E\u793A\uFF08contain\uFF0C\u7981\u6B62 cover \u4E8C\u6B21\u88C1\u5207\uFF09\uFF1B\u89D2\u6807\u6807\u300C\u5C40\u90E8\u622A\u56FE / \u5DF2\u7F16\u8F91\u300D\uFF0C\n   \u5C3A\u5BF8\u8BFB\u6570\u663E\u793A\u8F93\u51FA\u50CF\u7D20\uFF1B\u7F16\u8F91\u3001\u5220\u9664\u6309\u94AE\u5728\u56FE\u7247**\u4E0B\u65B9**\uFF0C\u4E0D\u5F97\u906E\u4F4F\u56FE\u7247\u5185\u5BB9\u3002 */\n.fb-screenshot-wrap {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 8px;\n}\n\n.fb-screenshot-thumb-box {\n  position: relative;\n  width: 100%;\n  border-radius: 10px;\n  border: 1px solid var(--fb-border);\n  background: var(--fb-bg-subtle);\n  overflow: hidden;\n  cursor: zoom-in;\n  display: flex;\n  flex-direction: column;\n}\n\n.fb-thumb-frame {\n  position: relative;\n  height: 116px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n  background: var(--fb-bg-subtle);\n}\n\n/* \u7F16\u8F91 / \u5220\u9664\u884C\uFF08\u56FE\u7247\u4E0B\u65B9\uFF09\uFF1A\u89E6\u63A7\u76EE\u6807 \u226544px\uFF0C\u7EDD\u4E0D\u8986\u76D6\u56FE\u7247\u5185\u5BB9\u3002 */\n.fb-thumb-actions {\n  display: flex;\n  gap: 8px;\n  padding: 6px 8px;\n  border-top: 1px solid var(--fb-border);\n  background: var(--fb-bg);\n}\n\n.fb-thumb-edit,\n.fb-thumb-remove {\n  flex: 1;\n  min-width: 44px;\n  min-height: 44px;\n  padding: 0 6px;\n  font-size: 12px;\n  line-height: 1;\n  border: 1px solid var(--fb-border-strong);\n  border-radius: 8px;\n  background: var(--fb-bg);\n  color: var(--fb-text);\n  cursor: pointer;\n}\n\n.fb-thumb-remove {\n  color: var(--fb-status-error-text);\n  border-color: var(--fb-status-error-border);\n}\n\n.fb-thumb-edit:disabled,\n.fb-thumb-remove:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n.fb-thumb-edit:focus-visible,\n.fb-thumb-remove:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 1px;\n}\n\n.fb-screenshot-thumb {\n  width: 100%;\n  height: 100%;\n  object-fit: contain; /* \u5B8C\u6574\u663E\u793A\uFF0C\u7981\u6B62 cover \u4E8C\u6B21\u88C1\u5207 */\n  display: block;\n}\n\n.fb-screenshot-badge {\n  position: absolute;\n  top: 8px;\n  left: 8px;\n  padding: 2px 8px;\n  border-radius: 6px;\n  background: rgba(0, 0, 0, 0.65);\n  color: #fff;\n  font-size: 11px;\n  font-weight: 500;\n  letter-spacing: 0.02em;\n  backdrop-filter: blur(4px);\n  -webkit-backdrop-filter: blur(4px);\n  pointer-events: none;\n}\n\n/* \u5C3A\u5BF8\u8BFB\u6570\uFF08\u8F93\u51FA\u50CF\u7D20\uFF09\uFF1A\u4E0E\u89D2\u6807\u540C\u5C42\u7684\u8F7B\u91CF\u6807\u8BB0 */\n.fb-screenshot-size {\n  position: absolute;\n  bottom: 8px;\n  left: 8px;\n  padding: 2px 6px;\n  border-radius: 6px;\n  background: rgba(0, 0, 0, 0.65);\n  color: #fff;\n  font-size: 10px;\n  font-weight: 500;\n  font-variant-numeric: tabular-nums;\n  letter-spacing: 0.02em;\n  pointer-events: none;\n}\n\n.fb-screenshot-zoom-hint {\n  position: absolute;\n  bottom: 8px;\n  right: 8px;\n  padding: 3px 8px;\n  border-radius: 6px;\n  background: rgba(0, 0, 0, 0.65);\n  color: #fff;\n  font-size: 11px;\n  font-weight: 500;\n  backdrop-filter: blur(4px);\n  -webkit-backdrop-filter: blur(4px);\n  pointer-events: none;\n  opacity: 0;\n  transition: opacity 0.15s ease;\n}\n\n.fb-screenshot-thumb-box:hover .fb-screenshot-zoom-hint {\n  opacity: 1;\n}\n\n.fb-screenshot-actions {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n/* \u9996\u4E2A\u622A\u56FE\u5165\u53E3\uFF1A\u9ED8\u8BA4 capture-mode=off \u7684\u5BBF\u4E3B\u91CC\u5B83\u662F**\u552F\u4E00**\u7684\u622A\u56FE\u65B9\u5F0F\uFF0C\n   \u56E0\u6B64\u6BD4\u300C\u91CD\u65B0\u622A\u56FE / \u79FB\u9664\u622A\u56FE\u300D\u66F4\u663E\u773C\uFF08\u4E3B\u8272\u586B\u5145\uFF09\uFF0C\u4F46\u4E0D\u4E0E\u300C\u63D0\u4EA4\u300D\u4E89\u4E3B\u6B21\u3002 */\n.fb-btn-capture {\n  min-height: 44px;\n  padding: 0 14px;\n  font-size: 13px;\n  font-weight: 500;\n  border-radius: 8px;\n  border: 1px solid var(--fb-accent);\n  background: var(--fb-accent);\n  color: #fff;\n  cursor: pointer;\n  transition: background 0.15s;\n}\n\n.fb-btn-capture:hover:not(:disabled) {\n  background: var(--fb-accent-hover);\n}\n\n.fb-btn-capture:disabled {\n  background: var(--fb-accent-disabled);\n  border-color: var(--fb-accent-disabled);\n  cursor: not-allowed;\n}\n\n/* \u6355\u83B7\u4E2D\uFF1A\u9762\u677F\u5728\u6B64\u671F\u95F4\u6574\u4F53 visibility:hidden\uFF08\u622A\u56FE\u91CC\u4E0D\u542B\u7EC4\u4EF6\u81EA\u8EAB UI\uFF09\uFF0C\n   \u6240\u4EE5\u8FD9\u4E2A\u52A0\u8F7D\u6001\u53EA\u53EF\u80FD\u88AB\u4F1A\u8BDD\u7ED3\u675F\u540E\u7684\u7528\u6237\u4E0E\u8F85\u52A9\u6280\u672F\u770B\u5230\u3002 */\n.fb-shot-area.is-capturing .fb-btn-capture {\n  cursor: progress;\n}\n\n.fb-btn-retake,\n.fb-btn-remove,\n.fb-btn-add-image {\n  min-height: 44px;\n  padding: 0 14px;\n  font-size: 13px;\n  font-weight: 500;\n  border-radius: 8px;\n  border: 1px solid var(--fb-border-strong);\n  background: var(--fb-bg);\n  color: var(--fb-text);\n  cursor: pointer;\n  transition: background 0.15s;\n}\n\n.fb-btn-retake:hover:not(:disabled),\n.fb-btn-remove:hover:not(:disabled),\n.fb-btn-add-image:hover:not(:disabled) {\n  background: var(--fb-bg-subtle-hover);\n}\n\n.fb-btn-retake:disabled,\n.fb-btn-remove:disabled,\n.fb-btn-add-image:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n/* \u9884\u89C8\u65C1\u63D0\u793A\u4E0E\u56FE\u7247\u9519\u8BEF\uFF08v12\uFF1A\u90E8\u5206\u5185\u5BB9\u672A\u5165\u56FE / \u670D\u52A1\u7AEF\u5355\u56FE\u964D\u7EA7 / \u4ECD\u8D85\u9650\uFF09 */\n.fb-shot-hint {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.4;\n  color: var(--fb-status-warn-text);\n  background: var(--fb-status-warn-bg);\n  border: 1px solid var(--fb-status-warn-border);\n  border-radius: 8px;\n  padding: 6px 10px;\n}\n\n.fb-shot-error {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.4;\n  color: var(--fb-status-error-text);\n  background: var(--fb-status-error-bg);\n  border: 1px solid var(--fb-status-error-border);\n  border-radius: 8px;\n  padding: 6px 10px;\n}\n\n/* \u62D6\u5165\u56FE\u7247\u65F6\u7684\u76EE\u6807\u6001 */\n.fb-body.is-dragover {\n  outline: 2px dashed var(--fb-accent);\n  outline-offset: -4px;\n  border-radius: 8px;\n}\n\n.fb-btn-remove {\n  color: var(--fb-status-error-text);\n  border-color: var(--fb-status-error-border);\n}\n\n.fb-btn-capture:focus-visible,\n.fb-btn-retake:focus-visible,\n.fb-btn-remove:focus-visible,\n.fb-zoom-close:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 2px;\n}\n\n/* \u7A84\u5C4F\uFF08\u79FB\u52A8\u7AEF\u5168\u5C4F\u9762\u677F\uFF09\uFF1A\u622A\u56FE\u64CD\u4F5C\u6309\u94AE\u7ED9\u5230\u89E6\u5C4F\u53EF\u70B9\u7684\u9AD8\u5EA6\uFF0C\u5E76\u5141\u8BB8\u6362\u884C */\n@media (max-width: 767.98px) {\n  .fb-screenshot-actions {\n    gap: 10px;\n  }\n\n  .fb-btn-capture,\n  .fb-btn-retake,\n  .fb-btn-remove {\n    padding: 7px 12px;\n    font-size: 13px;\n  }\n}\n\n/* ---- \u65E5\u5FD7\u9644\u4EF6\u533A\uFF08T4 \u53EF\u6298\u53E0\uFF09\uFF1A\u9ED8\u8BA4\u53EA\u663E\u793A\u7B80\u77ED\u6458\u8981\u884C ---- */\n.fb-logs-area {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.fb-logs-toggle {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  width: 100%;\n  min-height: 44px;\n  padding: 6px 12px;\n  border: 1px solid var(--fb-border);\n  border-radius: 10px;\n  background: var(--fb-bg-subtle);\n  color: var(--fb-text-secondary);\n  font: inherit;\n  font-size: 12px;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.fb-logs-toggle:hover {\n  background: var(--fb-bg-subtle-hover);\n}\n\n.fb-logs-toggle:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 2px;\n}\n\n.fb-logs-summary {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.fb-logs-chevron {\n  flex-shrink: 0;\n  transition: transform 0.18s ease;\n}\n\n.fb-logs-toggle[aria-expanded=\"true\"] .fb-logs-chevron {\n  transform: rotate(90deg);\n}\n\n.fb-logs-body {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.fb-logs-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: 12px;\n  color: var(--fb-text-secondary);\n}\n\n.fb-logs-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.fb-log-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 6px 10px;\n  border-radius: 6px;\n  background: var(--fb-bg-subtle);\n  border: 1px solid var(--fb-border);\n  font-size: 12px;\n  gap: 8px;\n}\n\n.fb-log-info {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  flex: 1;\n}\n\n.fb-log-name {\n  font-weight: 500;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.fb-log-badge {\n  padding: 1px 5px;\n  border-radius: 4px;\n  font-size: 10px;\n  font-weight: 500;\n  background: var(--fb-bg-subtle-hover);\n  color: var(--fb-text-secondary);\n}\n\n.fb-log-size {\n  color: var(--fb-text-tertiary);\n  font-size: 11px;\n}\n\n.fb-log-btns {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.fb-log-btn-preview,\n.fb-log-btn-remove,\n.fb-btn-add-log {\n  min-height: 44px;\n  padding: 6px 12px;\n  font-size: 12px;\n  font-weight: 500;\n  border-radius: 8px;\n  border: 1px solid var(--fb-border-strong);\n  background: var(--fb-bg);\n  color: var(--fb-text);\n  cursor: pointer;\n  transition: background 0.15s;\n}\n\n.fb-log-btn-preview:hover,\n.fb-log-btn-remove:hover,\n.fb-btn-add-log:hover {\n  background: var(--fb-bg-subtle-hover);\n}\n\n.fb-log-btn-remove {\n  color: var(--fb-status-error-text);\n  border-color: var(--fb-status-error-border);\n}\n\n.fb-log-status {\n  font-size: 12px;\n  color: var(--fb-text-secondary);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.fb-log-error {\n  font-size: 12px;\n  color: var(--fb-status-error-text);\n  background: var(--fb-status-error-bg);\n  border: 1px solid var(--fb-status-error-border);\n  padding: 4px 8px;\n  border-radius: 4px;\n}\n\n.fb-log-preview-modal {\n  position: fixed;\n  inset: 0;\n  z-index: calc(var(--fb-z-index, var(--fb-z-index-default)) + 25);\n  background: rgba(0, 0, 0, 0.6);\n  backdrop-filter: blur(8px);\n  -webkit-backdrop-filter: blur(8px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 24px;\n  box-sizing: border-box;\n  opacity: 0;\n  pointer-events: none;\n  visibility: hidden;\n  transition: opacity 0.2s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.2s;\n}\n\n.fb-log-preview-modal.is-open {\n  opacity: 1;\n  pointer-events: auto;\n  visibility: visible;\n}\n\n.fb-log-preview-card {\n  background: var(--fb-bg);\n  color: var(--fb-text);\n  border-radius: 12px;\n  padding: 16px;\n  max-width: 680px;\n  width: 100%;\n  max-height: 80vh;\n  display: flex;\n  flex-direction: column;\n  box-shadow: var(--fb-shadow);\n  border: 1px solid var(--fb-border);\n}\n\n.fb-log-preview-body {\n  overflow: auto;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n  font-size: 12px;\n  line-height: 1.4;\n  white-space: pre-wrap;\n  word-break: break-all;\n  background: var(--fb-bg-subtle);\n  padding: 12px;\n  border-radius: 6px;\n  margin: 12px 0;\n  flex: 1;\n}\n\n/* ---- \u622A\u56FE\u5927\u56FE\u5F39\u7A97 (Zoom Modal) ---- */\n.fb-zoom-modal {\n  position: fixed;\n  inset: 0;\n  z-index: calc(var(--fb-z-index, var(--fb-z-index-default)) + 20);\n  background: rgba(0, 0, 0, 0.82);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 32px;\n  box-sizing: border-box;\n  cursor: zoom-out;\n  opacity: 0;\n  pointer-events: none;\n  visibility: hidden;\n  transition: opacity 0.2s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.2s;\n}\n\n.fb-zoom-modal.is-open {\n  opacity: 1;\n  pointer-events: auto;\n  visibility: visible;\n}\n\n.fb-zoom-modal img {\n  max-width: 92vw;\n  max-height: 90vh;\n  object-fit: contain;\n  border-radius: 8px;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);\n}\n\n.fb-zoom-close {\n  position: absolute;\n  top: 20px;\n  right: 20px;\n  width: 36px;\n  height: 36px;\n  border-radius: 50%;\n  border: none;\n  background: rgba(255, 255, 255, 0.18);\n  color: #fff;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: background 0.15s;\n}\n\n.fb-zoom-close:hover {\n  background: rgba(255, 255, 255, 0.3);\n}\n\n/* ---- \u5934\u90E8\u53F3\u4FA7\u52A8\u4F5C\u7EC4\u4E0E\u670D\u52A1\u5668\u8BBE\u7F6E\u89C6\u56FE\uFF08T6\uFF09 ---- */\n.fb-header-actions {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  flex-shrink: 0;\n}\n\n.fb-icon-btn {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 32px;\n  height: 32px;\n  border: none;\n  background: transparent;\n  color: var(--fb-text-secondary);\n  border-radius: 50%;\n  cursor: pointer;\n  padding: 0;\n  transition: background 0.15s, color 0.15s;\n}\n\n.fb-icon-btn:hover {\n  background: var(--fb-bg-subtle-hover);\n  color: var(--fb-text);\n}\n\n.fb-icon-btn:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 2px;\n}\n\n.fb-settings {\n  flex: 1;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: 16px 18px 18px;\n  gap: 10px;\n}\n\n.fb-settings-title {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--fb-text);\n}\n\n.fb-settings-line {\n  margin: 0;\n  font-size: 12px;\n  color: var(--fb-text-secondary);\n  display: flex;\n  gap: 4px;\n  min-width: 0;\n}\n\n.fb-settings-label {\n  flex-shrink: 0;\n}\n\n.fb-settings-value {\n  color: var(--fb-text);\n  overflow-wrap: anywhere;\n  word-break: break-all;\n}\n\n.fb-server-input {\n  width: 100%;\n}\n\n.fb-settings-error {\n  margin: 0;\n  font-size: 12px;\n  color: var(--fb-status-error-text);\n  line-height: 1.4;\n}\n\n.fb-settings-hint {\n  margin: 0;\n  font-size: 12px;\n  color: var(--fb-status-warn-text);\n  line-height: 1.4;\n}\n\n.fb-settings-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.fb-settings-confirm {\n  border: 1px solid var(--fb-status-warn-border);\n  background: var(--fb-status-warn-bg);\n  color: var(--fb-status-warn-text);\n  border-radius: 10px;\n  padding: 10px 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  font-size: 12px;\n}\n\n.fb-settings-confirm-text {\n  margin: 0;\n  line-height: 1.5;\n}\n\n/* ---- v11 \u5BF9\u8BDD\u4E0E\u5386\u53F2\u89C6\u56FE ---- */\n.fb-badge {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 18px;\n  height: 18px;\n  padding: 0 5px;\n  border-radius: 9px;\n  background: #d70015;\n  color: #fff;\n  font-size: 11px;\n  font-weight: 600;\n  line-height: 1;\n}\n\n.fb-launcher-badge {\n  position: absolute;\n  top: -4px;\n  right: -4px;\n  box-shadow: 0 1px 4px rgba(0,0,0,0.2);\n}\n\n.fb-nav-tabs {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n}\n\n.fb-nav-btn {\n  background: transparent;\n  border: none;\n  font-size: 14px;\n  font-weight: 500;\n  color: var(--fb-text-secondary);\n  cursor: pointer;\n  min-height: 44px;\n  padding: 4px 12px;\n  border-radius: 6px;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.fb-nav-btn:hover {\n  background: var(--fb-bg-subtle-hover);\n  color: var(--fb-text);\n}\n\n.fb-nav-btn.active {\n  color: var(--fb-accent);\n  font-weight: 600;\n  background: var(--fb-bg-subtle);\n}\n\n.fb-history-view {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  overflow-y: auto;\n  gap: 8px;\n  padding: 12px 0;\n}\n\n.fb-history-item {\n  display: flex;\n  flex-direction: column;\n  padding: 10px 12px;\n  background: var(--fb-bg-subtle);\n  border-radius: 8px;\n  cursor: pointer;\n  border: 1px solid transparent;\n  text-decoration: none;\n  color: inherit;\n  transition: background 0.15s ease, border-color 0.15s ease;\n}\n\n.fb-history-item:hover {\n  background: var(--fb-bg-subtle-hover);\n  border-color: var(--fb-border);\n}\n\n.fb-history-item-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 4px;\n}\n\n.fb-history-title {\n  font-weight: 600;\n  font-size: 13px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  flex: 1;\n}\n\n.fb-history-tags {\n  display: flex;\n  gap: 4px;\n  align-items: center;\n}\n\n.fb-tag {\n  display: inline-flex;\n  padding: 2px 6px;\n  border-radius: 4px;\n  font-size: 11px;\n  font-weight: 500;\n  background: var(--fb-border);\n  color: var(--fb-text-secondary);\n}\n\n.fb-tag.waiting-admin {\n  background: var(--fb-status-warn-bg);\n  color: var(--fb-status-warn-text);\n}\n\n.fb-tag.waiting-user {\n  background: var(--fb-status-success-bg);\n  color: var(--fb-status-success-text);\n}\n\n.fb-tag.resolved {\n  background: var(--fb-bg-subtle-hover);\n  color: var(--fb-text-secondary);\n}\n\n.fb-dialogue-view {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  overflow: hidden;\n}\n\n.fb-dialogue-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 4px 0 10px;\n  border-bottom: 1px solid var(--fb-border);\n}\n\n.fb-dialogue-messages {\n  flex: 1;\n  overflow-y: auto;\n  padding: 12px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.fb-dialogue-msg {\n  display: flex;\n  flex-direction: column;\n  padding: 10px 12px;\n  border-radius: 8px;\n  font-size: 13px;\n  line-height: 1.4;\n}\n\n.fb-dialogue-msg.user {\n  background: var(--fb-bg-subtle);\n  border-left: 3px solid var(--fb-accent);\n}\n\n.fb-dialogue-msg.admin {\n  background: #eef2ff;\n  border-left: 3px solid #6366f1;\n}\n\n.fb-dialogue-msg.system {\n  background: var(--fb-status-warn-bg);\n  border-left: 3px solid var(--fb-status-warn-text);\n}\n\n.fb-dialogue-msg-meta {\n  display: flex;\n  justify-content: space-between;\n  font-size: 11px;\n  color: var(--fb-text-secondary);\n  margin-bottom: 4px;\n}\n\n.fb-dialogue-reply-box {\n  border-top: 1px solid var(--fb-border);\n  padding-top: 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n/* \u7A84\u5C4F\uFF08\u79FB\u52A8\u7AEF\u5168\u5C4F\u9762\u677F\uFF09\uFF1A\u8BBE\u7F6E\u64CD\u4F5C\u6309\u94AE\u7ED9\u5230\u89E6\u5C4F\u53EF\u70B9\u7684\u9AD8\u5EA6 */\n@media (max-width: 767.98px) {\n  .fb-settings-actions .fb-btn-secondary {\n    padding: 8px 14px;\n    font-size: 13px;\n  }\n}\n\n/* ---- \u5C0A\u91CD prefers-reduced-motion ----\n   \u7075\u611F\u7403\uFF1A\u53D6\u6D88\u5149\u6655\u6D41\u52A8\u4E0E\u7F29\u653E\uFF08\u62D6\u52A8\u5E73\u79FB\u662F\u529F\u80FD\u53CD\u9988\uFF0C\u4FDD\u7559\uFF09\u3002 */\n@media (prefers-reduced-motion: reduce) {\n  .fb-launcher,\n  .fb-panel,\n  .fb-submit,\n  .fb-close {\n    transition: none !important;\n  }\n  .fb-tab-launcher:hover,\n  .fb-tab-launcher:active,\n  .fb-submit:active {\n    transform: none !important;\n  }\n  .fb-orb,\n  .fb-orb:hover:not(.is-dragging),\n  .fb-orb:active:not(.is-dragging) {\n    transition: none !important;\n  }\n  .fb-orb:hover:not(.is-dragging),\n  .fb-orb:active:not(.is-dragging) {\n    transform: none !important;\n  }\n  .fb-orb-glow {\n    animation: none !important;\n  }\n}\n\n/* ---- v12 \u5168\u5C4F\u56FE\u7247\u7F16\u8F91\u5668 ----\n   \u8986\u76D6\u5728\u9762\u677F\u4E0E\u653E\u5927\u9884\u89C8\u4E4B\u4E0A\uFF1B\u6DF1\u8272\u5DE5\u4F5C\u53F0\u4EE5\u4FDD\u8BC1\u4EFB\u4F55\u622A\u56FE\u5185\u5BB9\u90FD\u6709\u53EF\u6BD4\u6027\u3002 */\n.fb-editor {\n  position: fixed;\n  inset: 0;\n  z-index: 2147483200;\n  display: flex;\n  flex-direction: column;\n  background: #1c1c1e;\n  color: #f5f5f7;\n}\n\n.fb-editor-toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 10px 16px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.12);\n  flex-wrap: wrap;\n}\n\n.fb-editor-tools {\n  display: flex;\n  gap: 6px;\n  flex-wrap: wrap;\n}\n\n.fb-editor-tool {\n  min-height: 44px;\n  padding: 0 14px;\n  font-size: 13px;\n  font-weight: 500;\n  border-radius: 8px;\n  border: 1px solid rgba(255, 255, 255, 0.24);\n  background: transparent;\n  color: #f5f5f7;\n  cursor: pointer;\n  transition: background 0.15s;\n}\n\n.fb-editor-tool:hover:not(:disabled) {\n  background: rgba(255, 255, 255, 0.12);\n}\n\n.fb-editor-tool.is-active {\n  background: var(--fb-accent);\n  border-color: var(--fb-accent);\n  color: #fff;\n}\n\n.fb-editor-tool:disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n.fb-editor-tool:focus-visible,\n.fb-editor-btn:focus-visible {\n  outline: 2px solid var(--fb-focus-ring);\n  outline-offset: 2px;\n}\n\n.fb-editor-actions {\n  display: flex;\n  gap: 8px;\n}\n\n.fb-editor-btn {\n  min-height: 44px;\n  padding: 0 16px;\n  font-size: 13px;\n  font-weight: 600;\n  border-radius: 8px;\n  border: 1px solid rgba(255, 255, 255, 0.24);\n  background: transparent;\n  color: #f5f5f7;\n  cursor: pointer;\n}\n\n.fb-editor-btn.is-primary {\n  background: var(--fb-accent);\n  border-color: var(--fb-accent);\n  color: #fff;\n}\n\n.fb-editor-btn.is-primary:hover:not(:disabled) {\n  background: var(--fb-accent-hover);\n}\n\n.fb-editor-btn:disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n.fb-editor-main {\n  flex: 1;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  padding: 12px 16px;\n  min-height: 0;\n  container-type: inline-size;\n}\n\n.fb-editor-stage {\n  flex: 1 1 320px;\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: auto;\n}\n\n/* T2\uFF1A\u72EC\u7ACB\u7684\u300C\u88C1\u526A\u7ED3\u679C\u300D\u9884\u89C8 + \u8F93\u51FA\u5C3A\u5BF8\uFF08\u684C\u9762\u53F3\u4FA7 280px\uFF09 */\n.fb-editor-result {\n  flex: 0 0 280px;\n  min-width: 220px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 12px;\n  border: 1px solid rgba(255, 255, 255, 0.14);\n  border-radius: 12px;\n  background: #2c2c2e;\n  overflow: hidden;\n}\n\n.fb-editor-result-title {\n  font-size: 12px;\n  color: #98989d;\n}\n\n.fb-editor-preview {\n  flex: 1 1 auto;\n  min-height: 0;\n  max-width: 100%;\n  max-height: 100%;\n  align-self: center;\n  background:\n    repeating-conic-gradient(#3a3a3c 0% 25%, #2c2c2e 0% 50%) 0 / 16px 16px;\n  border-radius: 8px;\n}\n\n.fb-editor-result-size {\n  font-size: 12px;\n  color: #c7c7cc;\n  font-variant-numeric: tabular-nums;\n}\n\n/* \u7A84\u5C4F\uFF08768px \u4EE5\u4E0B\uFF09\u6216\u5BB9\u5668\u8FC7\u7A84\uFF1A\u4E0A\u4E0B\u6392\u5217\uFF0C\u7ED3\u679C\u533A\u9AD8 160px */\n@container (max-width: 767px) {\n  .fb-editor-stage {\n    flex: 1 1 100%;\n  }\n  .fb-editor-result {\n    flex: 1 1 100%;\n    min-width: 0;\n    height: 160px;\n  }\n}\n\n@media (max-width: 767.98px) {\n  .fb-editor-stage {\n    flex: 1 1 100%;\n  }\n  .fb-editor-result {\n    flex: 1 1 100%;\n    min-width: 0;\n    height: 160px;\n  }\n}\n\n.fb-editor-canvas {\n  max-width: 100%;\n  max-height: 100%;\n  object-fit: contain;\n  background:\n    repeating-conic-gradient(#3a3a3c 0% 25%, #2c2c2e 0% 50%) 0 / 16px 16px;\n  border-radius: 4px;\n  cursor: crosshair;\n  touch-action: none; /* \u6307\u9488\u7ED8\u5236\u4E0D\u88AB\u624B\u52BF\u6EDA\u52A8\u62A2\u5360 */\n}\n\n.fb-editor-cropbar {\n  position: sticky;\n  bottom: 0;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-wrap: wrap;\n  gap: 12px;\n  padding: 10px 16px;\n  border-top: 1px solid rgba(255, 255, 255, 0.12);\n  background: #1c1c1e;\n}\n\n/* \u5B58\u5728\u672A\u5E94\u7528\u9009\u533A\u65F6\u7981\u7528\u300C\u4FDD\u5B58\u300D\u7684\u539F\u56E0\u8BF4\u660E */\n.fb-editor-save-hint {\n  font-size: 12px;\n  color: #ff9f0a;\n  line-height: 1.3;\n  max-width: 240px;\n}\n\n.fb-editor-crop-hint {\n  font-size: 12px;\n  color: #98989d;\n}\n\n.fb-editor-hint {\n  margin: 0;\n  padding: 8px 16px 12px;\n  font-size: 11px;\n  color: #98989d;\n  text-align: center;\n}\n\n/* ---- v12 \u6211\u7684\u53CD\u9988\uFF1A\u7B5B\u9009\u4E0E\u5206\u9875 ---- */\n.fb-history-filter-row {\n  display: flex;\n  padding: 8px 0;\n}\n\n.fb-history-filter {\n  flex: 1;\n  min-height: 44px;\n  padding: 6px 10px;\n  font-size: 13px;\n  font-family: inherit;\n  color: var(--fb-text);\n  background: var(--fb-bg);\n  border: 1px solid var(--fb-border-strong);\n  border-radius: 8px;\n}\n\n.fb-history-filter:focus-visible {\n  outline: 2px solid var(--fb-focus-ring);\n  outline-offset: 1px;\n}\n\n.fb-history-items {\n  flex: 1;\n  overflow-y: auto;\n}\n\n.fb-history-pager {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  padding: 8px 0;\n}\n\n.fb-history-pager .fb-btn-secondary {\n  min-height: 44px;\n  padding: 6px 14px;\n  font-size: 12px;\n}\n\n.fb-history-page-info {\n  font-size: 12px;\n  color: var(--fb-text-secondary);\n}\n\n/* ---- v12 \u5904\u7406\u8BF4\u660E ---- */\n.fb-resolution-note {\n  margin: 6px 0 0;\n  padding: 6px 10px;\n  font-size: 12px;\n  line-height: 1.4;\n  color: var(--fb-status-success-text);\n  background: var(--fb-status-success-bg);\n  border: 1px solid var(--fb-status-success-border);\n  border-radius: 8px;\n  white-space: pre-wrap;\n}\n\n/* ---- v12 \u5BF9\u8BDD\u9644\u4EF6\u4E0E\u56DE\u590D\u56FE\u7247 ---- */\n.fb-dialogue-attachment-img {\n  max-height: 100px;\n  border-radius: 4px;\n  border: 1px solid var(--fb-border);\n}\n\n.fb-reply-images {\n  margin-top: 2px;\n}\n\n.fb-reply-thumb {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  gap: 2px;\n}\n\n.fb-reply-thumb-img {\n  width: 48px;\n  height: 48px;\n  object-fit: contain;\n  border-radius: 6px;\n  border: 1px solid var(--fb-border);\n  cursor: zoom-in;\n}\n/* ---- T1 \u5C40\u90E8\u9009\u533A\u8986\u76D6\u5C42\uFF08\u51BB\u7ED3\u753B\u9762 + \u53EF\u8C03\u6574\u9009\u533A + \u4E09\u4E2A\u64CD\u4F5C\uFF09 ---- */\n.fb-region-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: calc(var(--fb-z-index, var(--fb-z-index-default)) + 30);\n  overflow: hidden;\n  background: #000;\n  cursor: crosshair;\n}\n\n.fb-region-bg {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: fill; /* \u51BB\u7ED3\u4F4D\u56FE\u94FA\u6EE1\u8986\u76D6\u5C42\uFF1A\u4E0E 0..1 \u5F52\u4E00\u5316\u5750\u6807\u4E00\u4E00\u5BF9\u5E94 */\n  pointer-events: none;\n  user-select: none;\n  -webkit-user-drag: none;\n}\n\n.fb-region-frame {\n  position: absolute;\n  box-sizing: border-box;\n  border: 1px solid rgba(255, 255, 255, 0.95);\n  /* \u5916\u90E8\u6697\u5316\u906E\u7F69\uFF08\u8986\u76D6\u5C42 overflow:hidden \u9650\u5236\u5728\u89C6\u53E3\u5185\uFF09 */\n  box-shadow: 0 0 0 9999px rgba(0, 0, 0, 0.45);\n  cursor: move;\n}\n\n.fb-region-frame:focus-visible {\n  outline: 2px solid var(--fb-accent);\n  outline-offset: 2px;\n}\n\n.fb-region-handle {\n  position: absolute;\n  width: 14px;\n  height: 14px;\n  box-sizing: border-box;\n  background: #fff;\n  border: 1px solid rgba(0, 0, 0, 0.55);\n  border-radius: 3px;\n}\n\n/* \u547D\u4E2D\u533A\u6269\u5230 ~34px\uFF08\u952E\u76D8\u7B49\u4EF7\u64CD\u4F5C\uFF1AShift+\u65B9\u5411\u952E\u7F29\u653E\uFF09 */\n.fb-region-handle::after {\n  content: \"\";\n  position: absolute;\n  inset: -10px;\n}\n\n.fb-region-handle[data-handle=\"nw\"] { left: -7px; top: -7px; cursor: nwse-resize; }\n.fb-region-handle[data-handle=\"n\"] { left: 50%; top: -7px; margin-left: -7px; cursor: ns-resize; }\n.fb-region-handle[data-handle=\"ne\"] { right: -7px; top: -7px; cursor: nesw-resize; }\n.fb-region-handle[data-handle=\"e\"] { right: -7px; top: 50%; margin-top: -7px; cursor: ew-resize; }\n.fb-region-handle[data-handle=\"se\"] { right: -7px; bottom: -7px; cursor: nwse-resize; }\n.fb-region-handle[data-handle=\"s\"] { left: 50%; bottom: -7px; margin-left: -7px; cursor: ns-resize; }\n.fb-region-handle[data-handle=\"sw\"] { left: -7px; bottom: -7px; cursor: nesw-resize; }\n.fb-region-handle[data-handle=\"w\"] { left: -7px; top: 50%; margin-top: -7px; cursor: ew-resize; }\n\n.fb-region-toolbar {\n  position: absolute;\n  left: 50%;\n  bottom: 24px;\n  transform: translateX(-50%);\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 12px;\n  max-width: calc(100vw - 32px);\n  padding: 12px 16px;\n  border-radius: 16px;\n  background: rgba(28, 28, 30, 0.94);\n  border: 1px solid rgba(255, 255, 255, 0.14);\n  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35);\n  cursor: default;\n}\n\n.fb-region-size {\n  font-size: 12px;\n  color: #c7c7cc;\n  font-variant-numeric: tabular-nums;\n}\n\n.fb-region-btn {\n  min-height: 44px;\n  padding: 0 16px;\n  border-radius: 980px;\n  border: 1px solid rgba(255, 255, 255, 0.24);\n  background: transparent;\n  color: #f5f5f7;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.fb-region-btn:hover {\n  background: rgba(255, 255, 255, 0.12);\n}\n\n.fb-region-use {\n  background: var(--fb-accent);\n  border-color: var(--fb-accent);\n  color: #fff;\n}\n\n.fb-region-use:hover {\n  background: var(--fb-accent-hover);\n}\n\n.fb-region-btn:focus-visible {\n  outline: 2px solid #fff;\n  outline-offset: 2px;\n}\n\n.fb-region-error {\n  position: absolute;\n  left: 50%;\n  bottom: 96px;\n  transform: translateX(-50%);\n  z-index: 2;\n  margin: 0;\n  max-width: calc(100vw - 32px);\n  padding: 8px 12px;\n  border-radius: 8px;\n  font-size: 12px;\n  line-height: 1.4;\n  color: #ff453a;\n  background: rgba(255, 69, 58, 0.16);\n  border: 1px solid rgba(255, 69, 58, 0.4);\n}\n";
